/// Behaviour table for CMIS 5.4.
pub static FSM_V5_4: FsmTable<CmisModuleStateSpace> = FsmTable {
    id: "CmisModuleStateMachine",
    initial: CmisModuleStateSpace::Reset,
    states: STATES_V5_4,
    transitions: TRANSITIONS_V5_4,
    terminal_exits: TERMINAL_EXITS_V5_4,
    timeouts: TIMEOUTS_V5_4,
};

/// The behaviour table for a CMIS catalog revision, or `None`.
///
/// Fail closed: only the catalog revisions the schema covers have a
/// table; every other context — other families, and CMIS versions
/// outside the catalog (e.g. 5.5, 3.1) — gets `None`. Consumers must
/// refuse to operate on an unsupported revision, never borrow the
/// nearest table.
pub fn for_revision(rev: openxcvr_core::Rev) -> Option<&'static FsmTable<CmisModuleStateSpace>> {
    if rev.family != openxcvr_core::Family::Cmis {
        return None;
    }
    match (rev.major, rev.minor) {
        (3, 0) => Some(&FSM_V3_0),
        (4, 0) => Some(&FSM_V4_0),
        (5, 0) => Some(&FSM_V5_0),
        (5, 1) => Some(&FSM_V5_1),
        (5, 2) => Some(&FSM_V5_2),
        (5, 3) => Some(&FSM_V5_3),
        (5, 4) => Some(&FSM_V5_4),
        _ => None,
    }
}

/// The behaviour table for a packed-BCD CMIS revision byte
/// (CMIS 5.3 § 8.2.1, e.g. `0x53` for 5.3), or `None` for any byte
/// outside the catalog revisions this machine covers.
pub fn for_rev_major_byte(byte: u8) -> Option<&'static FsmTable<CmisModuleStateSpace>> {
    match byte {
        0x30 => Some(&FSM_V3_0),
        0x40 => Some(&FSM_V4_0),
        0x50 => Some(&FSM_V5_0),
        0x51 => Some(&FSM_V5_1),
        0x52 => Some(&FSM_V5_2),
        0x53 => Some(&FSM_V5_3),
        0x54 => Some(&FSM_V5_4),
        _ => None,
    }
}
